'use client'

import { useEffect, useState } from 'react'

import { cn } from '@/lib/utils'

// Gerçek uygulamada build-time inject edilen sürüm/commit bilgisi — block'ta
// sabit demo değerleri.
const APP_VERSION = '1.4.0'
const GIT_SHA = 'a1b2c3d'
const CURRENT_USER = { id: 128, companyId: 42 }

const CONNECTION_STATUS = 'connected' as 'connected' | 'connecting' | 'disconnected'

const CONNECTION_DOT_CLASS = {
  connected: 'bg-status-online',
  connecting: 'bg-status-away',
  disconnected: 'bg-status-offline',
} as const

const CONNECTION_LABEL = {
  connected: 'Connected',
  connecting: 'Connecting…',
  disconnected: 'Disconnected',
} as const

/** Alanlar arası ince ayırıcı — tasarımdaki soluk nokta yerine 11px mono'da aynı işi gören bir çizgi. */
function Dot() {
  return <span aria-hidden="true" className="h-2.5 w-px shrink-0 bg-current opacity-30" />
}

export function AppFooter() {
  const [now, setNow] = useState<Date | null>(null)

  // Saniyelik saat — yalnızca görüntü amaçlı, sunucu/istemci ilk render
  // uyuşmazlığı olmasın diye mount sonrası set edilir.
  useEffect(() => {
    setNow(new Date())
    const id = setInterval(() => setNow(new Date()), 1000)
    return () => clearInterval(id)
  }, [])

  return (
    <footer className="flex h-[30px] shrink-0 items-center gap-2.5 overflow-hidden border-t bg-card px-3.5 font-medium font-mono text-[11px] text-text-faint whitespace-nowrap">
      <span className="flex min-w-0 items-center gap-2.5 overflow-hidden">
        <span>
          v{APP_VERSION} ({GIT_SHA})
        </span>
        <Dot />
        <span className="truncate">uid: {CURRENT_USER.id}</span>
        <Dot />
        <span className="truncate">cid: {CURRENT_USER.companyId}</span>
      </span>
      <span className="ms-auto flex shrink-0 items-center gap-2">
        <span className="flex items-center gap-1.5">
          <span className={cn('size-1.5 rounded-full', CONNECTION_DOT_CLASS[CONNECTION_STATUS])} />
          {CONNECTION_LABEL[CONNECTION_STATUS]}
        </span>
        <Dot />
        <span suppressHydrationWarning>
          {now?.toLocaleDateString(undefined, { day: '2-digit', month: 'short', year: 'numeric' }) ??
            '—'}
        </span>
        <Dot />
        <span className="text-text-secondary" suppressHydrationWarning>
          {now?.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit', second: '2-digit' }) ??
            '—'}
        </span>
      </span>
    </footer>
  )
}

'use client'

import { IconBuilding, IconSearch, IconTicket, IconUser } from '@tabler/icons-react'
import { useEffect, useState } from 'react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

// Backend'de 3 karakterin altında arama reddediliyor — burada da aynı eşik
// korunuyor ki davranış birebir örtüşsün.
const MIN_SEARCH_LENGTH = 3

const QUICK_COMMANDS = [
  { key: 'contact', label: 'New contact', icon: IconUser, className: 'bg-info-50 text-info-700' },
  {
    key: 'company',
    label: 'New company',
    icon: IconBuilding,
    className: 'bg-success-50 text-success-700',
  },
  {
    key: 'ticket',
    label: 'New ticket',
    icon: IconTicket,
    className: 'bg-warning-50 text-warning-700',
  },
] as const

// Sonuçlar gerçek bir arama servisinden değil, sabit bir demo listesinden
// istemci tarafında filtreleniyor — block "sıfır iş mantığı" prensibiyle
// gerçek bir müşteri/şirket API'sine bağlanmaz.
const RESULTS = [
  { id: '1', type: 'customer' as const, name: 'Alex Johnson', detail: 'alex@acme.com' },
  { id: '2', type: 'customer' as const, name: 'Maria Garcia', detail: '+1 555 0134' },
  { id: '3', type: 'company' as const, name: 'Acme Inc.', detail: 'acme.com' },
  { id: '4', type: 'company' as const, name: 'Globex Corp.', detail: 'globex.com' },
]

const RESULT_ICON = { customer: IconUser, company: IconBuilding } as const
const RESULT_LABEL = { customer: 'Contact', company: 'Company' } as const

/** Mac'te ⌘K, diğerlerinde Ctrl+K gösterir. */
function useShortcutLabel() {
  const [isMac, setIsMac] = useState(false)
  useEffect(() => {
    setIsMac(navigator.userAgent.includes('Mac'))
  }, [])
  return isMac ? '⌘K' : 'Ctrl+K'
}

export function GlobalSearchTrigger() {
  const [isOpen, setOpen] = useState(false)
  const shortcut = useShortcutLabel()

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key.toLowerCase() !== 'k' || !(event.metaKey || event.ctrlKey)) return
      event.preventDefault()
      setOpen((open) => !open)
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  return (
    <>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="text-text-secondary"
            onClick={() => setOpen(true)}
          >
            <IconSearch stroke={1.75} />
            <span className="sr-only">Search</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>Search ({shortcut})</TooltipContent>
      </Tooltip>

      <GlobalSearchDialog open={isOpen} onOpenChange={setOpen} />
    </>
  )
}

function GlobalSearchDialog({
  open,
  onOpenChange,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const [search, setSearch] = useState('')
  const shortcut = useShortcutLabel()

  useEffect(() => {
    if (!open) setSearch('')
  }, [open])

  const query = search.trim()
  const isTooShort = query.length > 0 && query.length < MIN_SEARCH_LENGTH
  const results = RESULTS.filter((result) =>
    result.name.toLowerCase().includes(query.toLowerCase()),
  )

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title="Search"
      description="Search contacts, companies and more"
      className="rounded-panel sm:max-w-155"
      commandProps={{ shouldFilter: false }}
    >
      <CommandInput placeholder="Search..." value={search} onValueChange={setSearch} />
      <CommandList className="max-h-[52vh] p-2">
        {query.length === 0 ? (
          <CommandGroup heading={<span className="text-eyebrow">Quick actions</span>}>
            {QUICK_COMMANDS.map((command) => {
              const Icon = command.icon
              return (
                <CommandItem key={command.key} className="gap-2.5">
                  <span
                    className={cn(
                      'flex size-8 shrink-0 items-center justify-center rounded-lg',
                      command.className,
                    )}
                  >
                    <Icon stroke={1.75} className="text-current" />
                  </span>
                  <span className="font-medium">{command.label}</span>
                </CommandItem>
              )
            })}
          </CommandGroup>
        ) : isTooShort ? (
          <CommandEmpty>Keep typing — at least {MIN_SEARCH_LENGTH} characters</CommandEmpty>
        ) : results.length === 0 ? (
          <CommandEmpty>No results found.</CommandEmpty>
        ) : (
          results.map((result) => {
            const Icon = RESULT_ICON[result.type]
            return (
              <CommandItem key={`${result.type}-${result.id}`} value={result.name} className="gap-2.5">
                <Icon stroke={1.75} />
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="truncate">{result.name}</span>
                  <span className="truncate text-text-secondary text-xs">{result.detail}</span>
                </span>
                <Badge variant="secondary" className="shrink-0">
                  {RESULT_LABEL[result.type]}
                </Badge>
              </CommandItem>
            )
          })
        )}
      </CommandList>
      <div className="flex items-center gap-4 border-t bg-surface-subtle px-4 py-2.5 text-text-faint text-xs">
        <span className="flex items-center gap-1.5">
          <kbd className="rounded-[5px] border bg-card px-1.5 py-0.5 font-mono font-semibold text-[10.5px]">
            ↑↓
          </kbd>
          Navigate
        </span>
        <span className="flex items-center gap-1.5">
          <kbd className="rounded-[5px] border bg-card px-1.5 py-0.5 font-mono font-semibold text-[10.5px]">
            ↵
          </kbd>
          Select
        </span>
        <span className="ms-auto">Press {shortcut} to open</span>
      </div>
    </CommandDialog>
  )
}

'use client'

import {
  IconBook,
  IconBuilding,
  IconCalendar,
  IconChevronDown,
  IconInbox,
  IconMail,
  IconMenu2,
  IconMessage,
  IconPlus,
  IconTicket,
  IconUser,
} from '@tabler/icons-react'
import { Fragment, useState } from 'react'

import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Separator } from '@/components/ui/separator'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

import { AppsGridPopover, UserStatusControl } from './app-header-tools'
import { NotificationsPopover } from './app-header-notifications'
import { GlobalSearchTrigger } from './app-header-search'

// "conversation" gerçek uygulamada canlı bir konuşma panelini aç/kapatır —
// burada sadece basılı görünüm (aria-pressed) ile taklit ediliyor.
const QUICK_ACTIONS = [
  { key: 'conversation', label: 'Conversations', icon: IconMessage, badge: 3 },
  { key: 'calendar', label: 'Calendar', icon: IconCalendar },
  { key: 'inbox', label: 'Inbox', icon: IconInbox },
  { key: 'knowledgeBase', label: 'Knowledge base', icon: IconBook },
] as const

// İlk üçü kayıt oluşturur, e-posta öncesinde ayırıcı var — tasarımdaki gibi.
const QUICK_ADD_ITEMS = [
  { key: 'contact', label: 'New contact', icon: IconUser },
  { key: 'company', label: 'New company', icon: IconBuilding },
  { key: 'ticket', label: 'New ticket', icon: IconTicket },
  { key: 'email', label: 'New email', icon: IconMail, separatorBefore: true },
] as const

function QuickActions() {
  const [activeKey, setActiveKey] = useState<string | null>(null)

  return (
    <div className="flex items-center gap-0.5">
      {QUICK_ACTIONS.map((action) => {
        const isConversation = action.key === 'conversation'
        const isActive = activeKey === action.key
        const Icon = action.icon

        return (
          <Tooltip key={action.key}>
            <TooltipTrigger asChild>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                aria-pressed={isConversation ? isActive : undefined}
                onClick={isConversation ? () => setActiveKey(isActive ? null : action.key) : undefined}
                className={cn(
                  'relative text-text-secondary',
                  isConversation && isActive && 'bg-accent text-foreground',
                )}
              >
                <Icon stroke={1.75} />
                {'badge' in action && (
                  <span className="absolute top-1 end-1 flex size-3.5 items-center justify-center rounded-full bg-primary text-[9px] text-primary-foreground tabular-nums">
                    {action.badge}
                  </span>
                )}
                <span className="sr-only">{action.label}</span>
              </Button>
            </TooltipTrigger>
            <TooltipContent>{action.label}</TooltipContent>
          </Tooltip>
        )
      })}

      <Separator orientation="vertical" className="mx-2 data-[orientation=vertical]:h-6" />

      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="h-9 gap-1.5 bg-surface-brand-subtle ps-2 pe-2.5 font-semibold text-[13px] text-primary tracking-[var(--tracking-tight)] hover:bg-primary/15 hover:text-primary"
          >
            <IconPlus stroke={2} />
            Quick add
            <IconChevronDown size={14} stroke={2} className="opacity-60" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-59">
          {QUICK_ADD_ITEMS.map((item) => {
            const Icon = item.icon
            return (
              <Fragment key={item.key}>
                {'separatorBefore' in item ? <DropdownMenuSeparator /> : null}
                <DropdownMenuItem>
                  <Icon stroke={1.75} />
                  {item.label}
                </DropdownMenuItem>
              </Fragment>
            )
          })}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

function HeaderTools() {
  return (
    <div className="ms-auto flex shrink-0 items-center gap-1.5">
      <NotificationsPopover />
      <UserStatusControl />
      <GlobalSearchTrigger />
      <AppsGridPopover />
    </div>
  )
}

type AppHeaderProps = {
  onOpenMobileMenu: () => void
}

export function AppHeader({ onOpenMobileMenu }: AppHeaderProps) {
  return (
    <header className="flex h-[var(--control-xl)] shrink-0 items-center gap-0.5 border-b bg-card px-3.5">
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="me-1 md:hidden"
        onClick={onOpenMobileMenu}
      >
        <IconMenu2 size={18} stroke={1.75} />
        <span className="sr-only">Open menu</span>
      </Button>
      <QuickActions />
      <HeaderTools />
    </header>
  )
}

'use client'

import { type ReactNode, useState } from 'react'

import { Sheet, SheetContent, SheetTitle } from '@/components/ui/sheet'
import { TooltipProvider } from '@/components/ui/tooltip'

import { AppFooter } from './app-footer'
import { AppHeader } from './app-header'
import { AppSidebar } from './app-sidebar'

type AppLayoutProps = {
  children: ReactNode
}

// Sıfır iş mantığı: yönlendirme, veri çekme yok — sayfa içeriği `children`
// olarak geçilir. Kendi router'ınıza bağlamak (aktif nav linki, sayfa geçiş
// animasyonu tetikleyicisi vb.) size kalır.
export function AppLayout({ children }: AppLayoutProps) {
  const [isMobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [pinned, setPinned] = useState(true)

  return (
    // Tooltip primitifi kendi provider'ını sarmıyor — sidebar ve header'daki
    // tüm tooltip'ler bu tek provider'ı paylaşır.
    <TooltipProvider>
      <div className="grid h-dvh grid-cols-1 overflow-hidden md:grid-cols-[auto_1fr]">
        <div className="hidden md:block">
          <AppSidebar pinned={pinned} onPinnedChange={setPinned} />
        </div>

        <Sheet open={isMobileMenuOpen} onOpenChange={setMobileMenuOpen}>
          <SheetContent side="left" className="w-[264px] p-0">
            <SheetTitle className="sr-only">Open menu</SheetTitle>
            <AppSidebar
              pinned={true}
              onNavigate={() => setMobileMenuOpen(false)}
              showToggle={false}
            />
          </SheetContent>
        </Sheet>

        <div className="grid min-h-0 grid-rows-[auto_1fr_auto]">
          <AppHeader onOpenMobileMenu={() => setMobileMenuOpen(true)} />
          <main className="min-h-0 overflow-y-auto p-6">
            <div className="animate-rise">{children}</div>
          </main>
          <AppFooter />
        </div>
      </div>
    </TooltipProvider>
  )
}

'use client'

import {
  type Icon,
  IconAddressBook,
  IconAdjustments,
  IconBell,
  IconBuilding,
  IconBuildingStore,
  IconChevronRight,
  IconHome,
  IconPackage,
  IconSettings,
  IconTicket,
} from '@tabler/icons-react'
import { type ReactElement, useState } from 'react'

import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

type LeafNavItem = { href: string; icon: Icon; label: string }
type GroupNavItem = { icon: Icon; label: string; children: NavItem[] }
type NavItem = LeafNavItem | GroupNavItem

function isGroup(item: NavItem): item is GroupNavItem {
  return 'children' in item
}

// Menü backend izin listesinden üretilene kadar burada sabit — block'ta
// zaten hep sabit kalır, kendi projenizde kendi route'larınızla değiştirin.
const NAV_ITEMS: NavItem[] = [
  { href: '#', icon: IconHome, label: 'Home' },
  { href: '#', icon: IconAddressBook, label: 'Contacts' },
  { href: '#', icon: IconBuilding, label: 'Companies' },
  { href: '#', icon: IconBell, label: 'Reminders' },
  { href: '#', icon: IconTicket, label: 'Tickets' },
  { href: '#', icon: IconPackage, label: 'Products' },
  { href: '#', icon: IconBuildingStore, label: 'Marketplace' },
  {
    icon: IconSettings,
    label: 'Settings',
    children: [{ href: '#', icon: IconAdjustments, label: 'Customization' }],
  },
]

const ACTIVE_HREF = '#home'

/** Daraltılmış (icon-rail) modda tooltip'e sarar, aksi halde olduğu gibi döner. */
function MaybeTooltip({
  collapsed,
  label,
  children,
}: {
  collapsed: boolean
  label: string
  children: ReactElement
}) {
  if (!collapsed) return children

  return (
    <Tooltip>
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent side="right">{label}</TooltipContent>
    </Tooltip>
  )
}

function NavLink({
  item,
  collapsed,
  depth,
  onNavigate,
}: {
  item: LeafNavItem
  collapsed: boolean
  depth: number
  onNavigate?: (() => void) | undefined
}) {
  const active = item.href === ACTIVE_HREF
  const Icon = item.icon

  return (
    <MaybeTooltip collapsed={collapsed} label={item.label}>
      <a
        href={item.href}
        onClick={onNavigate}
        aria-current={active ? 'page' : undefined}
        className={cn(
          'flex items-center rounded-control text-sm tracking-[var(--tracking-tight)] transition-colors',
          collapsed
            ? 'mx-auto size-10 justify-center'
            : cn('h-10 gap-2.5 px-2.5', depth > 0 && 'ps-8'),
          active
            ? 'bg-surface-brand-subtle font-semibold text-primary'
            : 'text-muted-foreground hover:bg-accent hover:text-foreground',
        )}
      >
        <Icon size={18} stroke={1.75} />
        <span className={cn('truncate', collapsed && 'sr-only')}>{item.label}</span>
      </a>
    </MaybeTooltip>
  )
}

function NavGroup({
  item,
  collapsed,
  depth,
  onNavigate,
}: {
  item: GroupNavItem
  collapsed: boolean
  depth: number
  onNavigate?: (() => void) | undefined
}) {
  // Grup, içinde aktif bir route varsa varsayılan olarak açık başlar.
  const [open, setOpen] = useState(() =>
    item.children.some((child) => !isGroup(child) && child.href === ACTIVE_HREF),
  )
  const Icon = item.icon

  // Daraltılmış rail modda accordion anlamsız — sadece ikon + tooltip, tıklanamaz.
  if (collapsed) {
    return (
      <MaybeTooltip collapsed={collapsed} label={item.label}>
        <div className="mx-auto flex size-10 items-center justify-center rounded-control text-sm tracking-[var(--tracking-tight)] text-muted-foreground">
          <Icon size={18} stroke={1.75} />
          <span className="sr-only">{item.label}</span>
        </div>
      </MaybeTooltip>
    )
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen((prev) => !prev)}
        aria-expanded={open}
        className={cn(
          'flex h-10 w-full cursor-pointer items-center gap-2.5 rounded-control px-2.5 text-sm tracking-[var(--tracking-tight)] text-muted-foreground hover:bg-accent hover:text-foreground',
          depth > 0 && 'ps-8',
        )}
      >
        <Icon size={18} stroke={1.75} />
        <span className="truncate">{item.label}</span>
        <IconChevronRight
          size={16}
          stroke={1.75}
          className={cn('ms-auto shrink-0 transition-transform', open && 'rotate-90')}
        />
      </button>
      {open && (
        <ul className="space-y-0.5">
          {item.children.map((child) => (
            <li key={child.label}>
              <NavItemRow item={child} collapsed={collapsed} depth={depth + 1} onNavigate={onNavigate} />
            </li>
          ))}
        </ul>
      )}
    </>
  )
}

function NavItemRow({
  item,
  collapsed,
  depth,
  onNavigate,
}: {
  item: NavItem
  collapsed: boolean
  depth: number
  onNavigate?: (() => void) | undefined
}) {
  return isGroup(item) ? (
    <NavGroup item={item} collapsed={collapsed} depth={depth} onNavigate={onNavigate} />
  ) : (
    <NavLink item={item} collapsed={collapsed} depth={depth} onNavigate={onNavigate} />
  )
}

type SidebarNavProps = {
  collapsed: boolean
  onNavigate?: (() => void) | undefined
}

export function SidebarNav({ collapsed, onNavigate }: SidebarNavProps) {
  return (
    <nav className={cn('min-h-0 flex-1 overflow-y-auto px-3 pb-2', collapsed ? 'pt-1.5' : 'pt-1')}>
      {!collapsed && (
        <p className="px-2.5 pt-2 pb-1.5 text-eyebrow text-text-faint">Menu</p>
      )}
      <ul className="space-y-0.5">
        {NAV_ITEMS.map((item) => (
          <li key={item.label}>
            <NavItemRow item={item} collapsed={collapsed} depth={0} onNavigate={onNavigate} />
          </li>
        ))}
      </ul>
    </nav>
  )
}

'use client'

import { IconCheck, IconCircleDot, IconSelector } from '@tabler/icons-react'
import { useState } from 'react'

import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

import { ProfileMenu } from './app-profile-menu'
import { SidebarNav } from './app-sidebar-nav'

const WORKSPACE = { name: 'Acme Inc.', initials: 'AI' }

function BrandMark({ collapsed }: { collapsed: boolean }) {
  return (
    <div className="flex items-center gap-2">
      <span className="flex size-7 shrink-0 items-center justify-center rounded-full bg-primary/10">
        <span className="size-2.5 rounded-full bg-primary" />
      </span>
      {collapsed ? null : <span className="truncate font-semibold text-lg tracking-tight">Spechy</span>}
    </div>
  )
}

type AppSidebarProps = {
  pinned: boolean
  onPinnedChange?: (pinned: boolean) => void
  onNavigate?: () => void
  showToggle?: boolean
}

export function AppSidebar({
  pinned,
  onPinnedChange = () => {},
  onNavigate,
  showToggle = true,
}: AppSidebarProps) {
  const [hovering, setHovering] = useState(false)
  const [workspaceMenuOpen, setWorkspaceMenuOpen] = useState(false)
  const [profileMenuOpen, setProfileMenuOpen] = useState(false)

  // Pin kapalıysa sidebar yalnızca hover'dayken genişler (rail deseni).
  // Workspace ya da profil dropdown'ı açıkken de daralma engellenir — aksi
  // halde portal'da açık kalan menü, daralan layout'un altında görsel
  // olarak kopuk kalır. Mobil Sheet varyantında (showToggle=false) collapse
  // tamamen devre dışı.
  const collapsed = showToggle && !pinned && !hovering && !workspaceMenuOpen && !profileMenuOpen
  const toggleLabel = pinned ? 'Unpin sidebar' : 'Pin sidebar'

  const workspaceAvatar = (
    <Avatar className={cn('rounded-lg', collapsed ? 'size-6.5' : 'size-7')}>
      <AvatarFallback className="rounded-lg bg-primary font-bold text-primary-foreground text-xs">
        {WORKSPACE.initials}
      </AvatarFallback>
    </Avatar>
  )

  // JWT'de tek şirket var — liste her zaman tek öğeli, ama dropdown kabuğu
  // çoklu workspace'e taşınabilecek şekilde bugünden hazır.
  const workspaceMenuContent = (
    <DropdownMenuContent align="start" className="w-59">
      <p className="px-2 pt-1.5 pb-1 text-eyebrow text-text-faint">Select workspace</p>
      <DropdownMenuItem className="gap-2.5">
        {workspaceAvatar}
        <span className="min-w-0 flex-1 truncate">{WORKSPACE.name}</span>
        <IconCheck size={16} stroke={1.75} className="shrink-0 text-primary" />
      </DropdownMenuItem>
    </DropdownMenuContent>
  )

  return (
    <aside
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
      className={cn(
        'flex h-full flex-col border-e bg-card transition-[width] duration-200',
        collapsed ? 'w-16' : 'w-[264px]',
      )}
    >
      <div
        className={cn(
          'flex h-[var(--control-xl)] shrink-0 items-center border-b',
          collapsed ? 'justify-center px-2' : 'justify-between gap-2 ps-4 pe-3',
        )}
      >
        <BrandMark collapsed={collapsed} />
        {collapsed || !showToggle ? null : (
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-pressed={pinned}
            onClick={() => onPinnedChange(!pinned)}
          >
            <IconCircleDot
              size={17}
              stroke={1.75}
              className={pinned ? 'text-primary' : 'text-text-secondary'}
            />
            <span className="sr-only">{toggleLabel}</span>
          </Button>
        )}
      </div>

      {collapsed ? (
        <div className="flex shrink-0 flex-col items-center gap-1.5 pt-3 pb-1">
          <DropdownMenu open={workspaceMenuOpen} onOpenChange={setWorkspaceMenuOpen}>
            <Tooltip>
              <TooltipTrigger asChild>
                <DropdownMenuTrigger asChild>
                  <Button type="button" variant="ghost" size="icon">
                    {workspaceAvatar}
                    <span className="sr-only">{WORKSPACE.name}</span>
                  </Button>
                </DropdownMenuTrigger>
              </TooltipTrigger>
              <TooltipContent side="right">{WORKSPACE.name}</TooltipContent>
            </Tooltip>
            {workspaceMenuContent}
          </DropdownMenu>
        </div>
      ) : (
        <div className="shrink-0 px-3 pt-3.5 pb-1.5">
          <DropdownMenu open={workspaceMenuOpen} onOpenChange={setWorkspaceMenuOpen}>
            <DropdownMenuTrigger asChild>
              <Button
                type="button"
                variant="ghost"
                className="h-12 w-full justify-between gap-2.5 rounded-control border bg-card px-2.5 shadow-xs"
              >
                <span className="flex min-w-0 items-center gap-2.5 overflow-hidden">
                  {workspaceAvatar}
                  <span className="flex min-w-0 flex-col items-start">
                    <span className="truncate text-sm tracking-[var(--tracking-tight)]">
                      {WORKSPACE.name}
                    </span>
                    <span className="truncate font-medium text-[11px] text-text-secondary">
                      Workspace
                    </span>
                  </span>
                </span>
                <IconSelector size={16} stroke={1.75} className="shrink-0 text-text-faint" />
              </Button>
            </DropdownMenuTrigger>
            {workspaceMenuContent}
          </DropdownMenu>
        </div>
      )}

      <SidebarNav collapsed={collapsed} onNavigate={onNavigate} />

      <ProfileMenu collapsed={collapsed} onOpenChange={setProfileMenuOpen} />
    </aside>
  )
}
